{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_D2C_Revenue_Performance AS WITH Targets AS ( SELECT DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Date, t.Type, CAST(REPLACE(t.Target, \',\', \'\') AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Daily_Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM `MapleMonk.Zouk_Sales_Target` t, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ) , Affiliate_Sales_Daily AS ( SELECT DATE_ADD(DATE(a.Start_Date), INTERVAL n DAY) AS Date, CAST(a.Revenue AS FLOAT64) / (DATE_DIFF(DATE(a.End_Date), DATE(a.Start_Date), DAY) + 1) AS Revenue, CAST(a.Net_Revenue AS FLOAT64) / (DATE_DIFF(DATE(a.End_Date), DATE(a.Start_Date), DAY) + 1) AS Net_Revenue FROM `MapleMonk.Zouk_Affiliate_Sales` a, UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(a.End_Date), DATE(a.Start_Date), DAY))) AS n ) , DTC_PandL AS ( SELECT Date, FINAL_MARKETPLACE, new_customer_flag, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(return_mrp_sales, 0)) AS MRP_Sales, SUM(IFNULL(BAU_MRP_SALES, 0)) - SUM(IFNULL(return_mrp_sales, 0)) - SUM(IFNULL(BAU_DISCOUNT, 0)) - SUM(IFNULL(TRADE_MARGIN, 0)) + SUM(IFNULL(return_trade_margin, 0)) - SUM(IFNULL(Returns, 0)) - SUM(IFNULL(gst, 0)) + SUM(IFNULL(Return_GST, 0)) AS Net_Revenue FROM `MapleMonk.zouk_pandl_DTC` GROUP BY Date, FINAL_MARKETPLACE, new_customer_flag ), Metric_DTC_MRP AS ( SELECT t.Date, \'DTC MRP\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() THEN d.MRP_Sales ELSE 0 END) AS Actual FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'mrp\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ) , Metric_DTC_NetRevenue AS ( SELECT t.Date, \'DTC Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() THEN d.Net_Revenue ELSE 0 END) AS Actual FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'net mrp\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_App_Revenue AS ( SELECT t.Date, \'App Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() AND LOWER(d.FINAL_MARKETPLACE) LIKE \'%app%\' THEN d.Net_Revenue ELSE 0 END) AS Actual FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%app%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_New_User_Revenue AS ( SELECT t.Date, \'New User Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() AND LOWER(d.new_customer_flag) = \'new\' THEN d.Net_Revenue ELSE 0 END) AS Actual FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%new%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_Repeat_User_Revenue AS ( SELECT t.Date, \'Repeat User Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN d.Date < CURRENT_DATE() AND LOWER(d.new_customer_flag) = \'repeat\' THEN d.Net_Revenue ELSE 0 END) AS Actual FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%retention%\' ) t LEFT JOIN DTC_PandL d ON t.Date = d.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ), Metric_Affiliate_Revenue AS ( SELECT t.Date, \'Affiliate Revenue\' AS Metric, t.Daily_Target AS Target, t.days_remaining, t.no_of_days, SUM(CASE WHEN a.Date < CURRENT_DATE() THEN a.Net_Revenue ELSE 0 END) AS Actual FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY Date, LOWER(Type) ORDER BY Date) AS rn FROM Targets WHERE LOWER(Type) LIKE \'%affliates%\' ) t LEFT JOIN Affiliate_Sales_Daily a ON t.Date = a.Date WHERE t.rn = 1 GROUP BY 1,3,4,5 ) SELECT * FROM Metric_DTC_NetRevenue UNION ALL SELECT * FROM Metric_DTC_MRP UNION ALL SELECT * FROM Metric_App_Revenue UNION ALL SELECT * FROM Metric_New_User_Revenue UNION ALL SELECT * FROM Metric_Repeat_User_Revenue UNION ALL SELECT * FROM Metric_Affiliate_Revenue ORDER BY Date, Metric;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            